def transform(grid):
    """Stamp the colored source object at each singleton marker's location."""
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    counts = {}
    for row in grid:
        for v in row:
            if v != bg:
                counts[v] = counts.get(v, 0) + 1
    # In these demonstrations, the marker color is the least frequent non-background color;
    # the remaining non-background cells form the source object.
    marker = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    source = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != marker]
    if not pts or not source:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c, v in source), max(r for r, c, v in source)
    c0, c1 = min(c for r, c, v in source), max(c for r, c, v in source)
    # Source coordinates relative to its bounding-box center, using integer center.
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    rel = [(r-ar, c-ac, v) for r, c, v in source]
    out = [row[:] for row in grid]
    for r, c in pts:
        for dr, dc, v in rel:
            rr, cc = r+dr, c+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out

